contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        // Drive c through its public entry points.
        c.Put{value: putAmount}(unlockTime);

        uint minSum = c.MinSum();
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(地址(this));

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlockTime, uint afterBalance) = c.Acc(地址(this));

        // General rule: Collect must revert when and only when the caller's
        // balance is zero, below MinSum, or less than the requested amount;
        // otherwise it succeeds and reduces the balance by exactly collectAmount.
        if (beforeBalance == 0 || beforeBalance < minSum || beforeBalance < collectAmount) {
            assert(reverted);
        } else {
            assert(!reverted && afterBalance == beforeBalance - collectAmount);
        }
    }

    receive() external payable {}
}

